#include <iostream>
#include <iomanip>
#include <string>

int main() {
    std::string nom;
    std::getline(std::cin, nom);
    int a, b, c;
    std::cin >> a >> b >> c;
    double moyenne = static_cast<double>(a + b + c) / 3;
    std::cout << nom << " : " << std::fixed << std::setprecision(2) << moyenne << "\n";
    return 0;
}

