#include <iostream>
#include <iomanip>
#include <string>

int main() {
    std::string client;
    std::getline(std::cin, client);
    int prix, tas;
    std::cin >> prix >> tas;
    int total = prix * tas;
    std::cout << "Client : " << client << "\n";
    std::cout << "Total : " << total << " FCFA\n";
    std::cout << "Prix moyen par tas : " << std::fixed << std::setprecision(1) << static_cast<double>(total) / tas << " FCFA\n";
    return 0;
}
